package ca.yorku.eecs3311.coursepilot.application.dto;
import ca.yorku.eecs3311.coursepilot.domain.model.*; import java.util.*;
public record QuizQuestionResponse(Long id, QuizQuestionType type, String prompt, List<String> options, String correctAnswer, String referenceAnswer, List<FlashcardSourceResponse> sources){public QuizQuestionResponse{options=List.copyOf(options);sources=List.copyOf(sources);} public static QuizQuestionResponse from(QuizQuestion q){List<String> options=List.of();try{if(q.getOptionsJson()!=null)options=new com.fasterxml.jackson.databind.ObjectMapper().readValue(q.getOptionsJson(),new com.fasterxml.jackson.core.type.TypeReference<List<String>>(){});}catch(Exception ignored){}return new QuizQuestionResponse(q.getId(),q.getType(),q.getPrompt(),options,q.getCorrectAnswer(),q.getReferenceAnswer(),q.getSources().stream().map(s->new FlashcardSourceResponse(s.getDocument().getId(),s.getDocument().getOriginalFilename(),s.getChunkId(),s.getChunkIndex(),s.getPageStart(),s.getPageEnd())).toList());}}
